            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
