    /// @notice Computes the result of `x` raised to the power of `y`, scaled by `b`.
    /// @param x The base value.
    /// @param y The exponent value.
    /// @param b The scaling factor.
    /// @return z The result of `x^y` scaled by `b`.
    function rpow(uint256 x, uint256 y, uint256 b) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
            // `x` is zero.
            if iszero(x) {
                // If `y` is zero, return `b` (0^0 = 1).
                z := mul(b, iszero(y))
            }
            // `x` is non-zero.
            if x {
                z := b
                for {} 1 {} {
                    // If `y` is odd.
                    if and(y, 1) {
                        // z = z * x, rounding.
                        let zz := mul(z, x)
                        // Revert if overflow.
                    }
                    // y = y / 2.
                    y := shr(1, y)
                    // If `y` is zero, break.
                    if iszero(y) { break }
                    // x = x * x, rounding.
                    let xx := mul(x, x)
                    // Revert if overflow.
                    x := xx
                }
            }
        }
    }

