    /// @notice Computes the integer square root of a given number using the Babylonian method.
    /// @param x The number to compute the square root of.
    /// @return z The integer square root of `x`.
    function sqrt(uint256 x) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
            // `z` is the initial estimate.
            z := 181
            // Calculate the initial shift value.
            let r := shl(7, gt(x, 0xffffffffffffffffffffffffffffffffff))
            r := or(r, shl(6, gt(shr(r, x), 0xffffffffffffffff)))
            r := or(r, shl(5, gt(shr(r, x), 0xffffffff)))
            r := or(r, shl(4, gt(shr(r, x), 0xffff)))
            r := or(r, shl(3, gt(shr(r, x), 0xff)))
            r := or(r, shl(2, gt(shr(r, x), 0xf)))
            r := or(r, shl(1, gt(shr(r, x), 0x3)))
            r := or(r, gt(shr(r, x), 0x1))
            // Adjust `z` based on the calculated shift.
            z := shr(div(r, 2), add(shr(1, x), shl(95, 1)))
            // Perform 7 iterations of the Babylonian method.
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            // Ensure the result is the floor of the square root.
            z := sub(z, lt(div(x, z), z))
        }
    }

    /// @notice Computes the cube root of a given unsigned integer `x`.
    /// @param x The unsigned integer for which the cube root is to be computed.
    /// @return z The cube root of `x`, rounded down to the nearest integer.
    function cbrt(uint256 x) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
            // Initial estimate.
            let r := shl(7, gt(x, 0xffffffffffffffffffffffffffffffffff))
            r := or(r, shl(6, gt(shr(r, x), 0xffffffffffffffff)))
            r := or(r, shl(5, gt(shr(r, x), 0xffffffff)))
            r := or(r, shl(4, gt(shr(r, x), 0xffff)))
            r := or(r, shl(3, gt(shr(r, x), 0xff)))
            r := or(r, shl(2, gt(shr(r, x), 0xf)))
            r := or(r, shl(1, gt(shr(r, x), 0x3)))
            r := or(r, gt(shr(r, x), 0x1))
            z := add(1, div(r, 3))
            z := shl(div(mul(z, 64), 3), 1)
            // Newton-Raphson iterations.
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            // Adjust for floor.
            let zz := mul(mul(z, z), z)
            z := sub(z, lt(x, zz))
        }
    }

    /// @notice Computes the square root of a given value scaled by 10^18 (WAD) with precision.
    /// @param x The input value to compute the square root for.
    /// @return z The square root of the input value, scaled by 10^9 for precision.
    function sqrtWad(uint256 x) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
            // For small x, compute directly.
            if iszero(gt(x, 0xffffffffffffffffffffffffffffffffff)) {
                z := sqrt(mul(x, 1000000000000000000))
            }
            // For large x, compute using fullMulDiv.
            if gt(x, 0xffffffffffffffffffffffffffffffffff) {
                let s := sqrt(x)
                z := add(
                    mul(s, 1000000000),
                    div(mul(sub(x, mul(s, s)), 1000000000), add(s, s))
                )
            }
        }
    }

    /// @notice Computes the cube root of a given value `x` scaled by 10^18 (Wad precision).
    /// @param x The input value for which the cube root is to be calculated, scaled by 10^18.
    /// @return z The cube root of `x`, scaled by 10^18.
    function cbrtWad(uint256 x) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
            // For small x, compute directly.
            if iszero(gt(x, 0xffffffffffffffffffffffffffffffffff)) {
                z := cbrt(mul(x, mul(1000000000000000000, 1000000000000000000)))
            }
            // For large x, compute using approximation.
            if gt(x, 0xffffffffffffffffffffffffffffffffff) {
                let c := cbrt(x)
                z := add(
                    mul(c, mul(1000000000, 1000000000)),
                    div(
                        mul(sub(x, mul(mul(c, c), c)), mul(1000000000, 1000000000)),
                        mul(3, mul(c, c))
                    )
                )
            }
        }
    }

