    /// @notice Internal function to decompose a number into its mantissa and exponent components.
    /// @param x The input number to be decomposed.
    /// @return mantissa The mantissa component of the number.
    /// @return exponent The exponent component of the number.
    function sci(uint256 x) internal pure returns (uint256 mantissa, uint256 exponent) {
        /// @solidity memory-safe-assembly
        assembly {
            mantissa := x
            if mantissa {
                if iszero(mod(mantissa, 1e33)) { mantissa := div(mantissa, 1e33) exponent := add(exponent, 33) }
                if iszero(mod(mantissa, 1e19)) { mantissa := div(mantissa, 1e19) exponent := add(exponent, 19) }
                if iszero(mod(mantissa, 1e12)) { mantissa := div(mantissa, 1e12) exponent := add(exponent, 12) }
                if iszero(mod(mantissa, 1e6))  { mantissa := div(mantissa, 1e6)  exponent := add(exponent, 6)  }
                if iszero(mod(mantissa, 1e4))  { mantissa := div(mantissa, 1e4)  exponent := add(exponent, 4)  }
                if iszero(mod(mantissa, 1e2))  { mantissa := div(mantissa, 1e2)  exponent := add(exponent, 2)  }
                if iszero(mod(mantissa, 1e1))  { mantissa := div(mantissa, 1e1)  exponent := add(exponent, 1)  }
            }
        }
    }

    /// @notice Packs a scientific notation value into a single uint256.
    /// @param x The input value to be packed.
    /// @return packed The packed value combining the mantissa and exponent.
    function packSci(uint256 x) internal pure returns (uint256 packed) {
        /// @solidity memory-safe-assembly
        assembly {
            let mantissa := x
            let exponent := 0
            if mantissa {
                if iszero(mod(mantissa, 1e33)) { mantissa := div(mantissa, 1e33) exponent := add(exponent, 33) }
                if iszero(mod(mantissa, 1e19)) { mantissa := div(mantissa, 1e19) exponent := add(exponent, 19) }
                if iszero(mod(mantissa, 1e12)) { mantissa := div(mantissa, 1e12) exponent := add(exponent, 12) }
                if iszero(mod(mantissa, 1e6))  { mantissa := div(mantissa, 1e6)  exponent := add(exponent, 6)  }
                if iszero(mod(mantissa, 1e4))  { mantissa := div(mantissa, 1e4)  exponent := add(exponent, 4)  }
                if iszero(mod(mantissa, 1e2))  { mantissa := div(mantissa, 1e2)  exponent := add(exponent, 2)  }
                if iszero(mod(mantissa, 1e1))  { mantissa := div(mantissa, 1e1)  exponent := add(exponent, 1)  }
            }
            // Revert if mantissa > 249 bits.
            if gt(mantissa, 0x01ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff) {
                mstore(0x00, 0x4e487b71) // `MantissaOverflow()`.
                revert(0x1c, 0x04)
            }
            // Pack mantissa and exponent.
            packed := or(shl(7, mantissa), and(exponent, 0x7f))
        }
    }

