    function unpackSci(uint256 packed) internal pure returns (uint256 unpacked) {
        /// @solidity memory-safe-assembly
        assembly {
            let coefficient := shr(7, packed)
            let exponent := and(packed, 0x7f)
            unpacked := mul(coefficient, exp(10, exponent))
        }
    }

