            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            z := div(add(mul(2, z), div(x, mul(z, z))), 3)
            // Adjust for floor.
            let zz := mul(mul(z, z), z)
            z := sub(z, lt(x, zz))
        }
    }

    /// @notice Computes the square root of a given value scaled by 10^18 (WAD) with precision.
