    /// @notice Performs linear interpolation (lerp) between two values `a` and `b` based on a parameter `t` within a range [begin, end].
    /// @param a The starting value of the interpolation.
    /// @param b The ending value of the interpolation.
    /// @param t The parameter determining the interpolation point.
    /// @param begin The start of the interpolation range.
    /// @param end The end of the interpolation range.
    /// @return The interpolated value between `a` and `b` based on `t`.
    function lerp(uint256 a, uint256 b, uint256 t, uint256 begin, uint256 end) internal pure returns (uint256) {
        if (begin > end) {
            t = end - t + begin;
            (begin, end) = (end, begin);
        }
        if (t <= begin) return a;
        if (t >= end) return b;
        if (b >= a) return a + fullMulDiv(b - a, t - begin, end - begin);
        return a - fullMulDiv(a - b, t - begin, end - begin);
    }

